        )
        after = self._evaluate_definition(
            flag_key, forecast_revision, candidate, context
        )
        if before["enabled"] != after["enabled"]:
            try:
                impacted.add(context.get("subject_id"))
            except TypeError:
                raise InvalidRolloutChangeError("subject_id 必须可哈希")

