            except TypeError:
                raise InvalidRolloutChangeError("subject_id 必须可哈希")

    total_impacted |= impacted
    stage_results.append(
        {
            "name": stage["name"],
            "percentage": stage["percentage"],
            "index": stage["index"],
            "forecast_revision": forecast_revision,
            "impacted": sorted(impacted, key=str),
